-- Complete replay guards for master-data/order/admin request-key operations.
set statement_timeout='30s';
set lock_timeout='5s';


create or replace function public.salon_create_customer(
  p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,
  p_display_name text,p_phone text default null,p_birthday date default null,
  p_owner_staff_id bigint default null,p_source text default 'walkin',p_tags text[] default '{}'
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_customer_id bigint;v_phone text;v_name text:=btrim(coalesce(p_display_name,''));
  v_source text:=btrim(coalesce(p_source,''));v_tags text[];v_response jsonb;
begin
  perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'customers','write');
  if v_name='' or length(v_name)>100 then raise exception '顾客姓名不能为空且不能超过100字';end if;
  v_phone:=regexp_replace(coalesce(p_phone,''),'[^0-9]','','g');
  if v_phone='' then v_phone:=null;elsif v_phone !~ '^1[0-9]{10}$' then raise exception '手机号必须为11位';end if;
  if v_source not in ('walkin','appointment','referral','online','import','other') then raise exception '顾客来源无效';end if;
  select coalesce(array_agg(distinct btrim(x) order by btrim(x)) filter(where btrim(x)<>''),'{}'::text[]) into v_tags from unnest(coalesce(p_tags,'{}')) x;
  if cardinality(v_tags)>20 or exists(select 1 from unnest(v_tags) x where length(x)>30) then raise exception '顾客标签最多20个且每个不超过30字';end if;
  v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'customer_create','customer_payload',hashtextextended(jsonb_build_object('name',v_name,'phone',v_phone,'birthday',p_birthday,'owner',p_owner_staff_id,'source',v_source,'tags',v_tags)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_display_name',p_display_name,'p_phone',p_phone,'p_birthday',p_birthday,'p_owner_staff_id',p_owner_staff_id,'p_source',p_source,'p_tags',p_tags),'customers','write');
  if v_request.completed_at is not null then return v_request.response_json;end if;
  if p_owner_staff_id is not null and not exists(select 1 from public.salon_staff s where s.organization_id=p_organization_id and s.store_id=p_store_id and s.id=p_owner_staff_id and s.employment_status='active') then raise exception '负责人不是当前门店在职员工';end if;
  begin
    insert into public.salon_customers(organization_id,display_name,phone_normalized,birthday)
      values(p_organization_id,v_name,v_phone,p_birthday) returning id into v_customer_id;
  exception when unique_violation then raise exception '该手机号已存在顾客档案';end;
  insert into public.salon_customer_store_relations(organization_id,store_id,customer_id,owner_staff_id,source,tags,first_visit_at)
    values(p_organization_id,p_store_id,v_customer_id,p_owner_staff_id,v_source,v_tags,now());
  insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json)
    values(p_organization_id,p_store_id,p_actor_staff_id,'customer',v_customer_id::text,'create',jsonb_build_object('displayName',v_name,'source',v_source,'tags',v_tags));
  v_response:=jsonb_build_object('customerId',v_customer_id,'status','active');
  update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;
  return v_response;
end $$;

create or replace function public.salon_set_customer_status(
  p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_customer_id bigint,
  p_request_key text,p_status text,p_reason text
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_customer public.salon_customers;v_reason text:=btrim(coalesce(p_reason,''));v_response jsonb;
begin
  perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'customers','write');
  v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'customer_status','customer_status_'||coalesce(p_status,''),p_customer_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_customer_id',p_customer_id,'p_status',p_status,'p_reason',p_reason),'customers','write');
  if v_request.completed_at is not null then return v_request.response_json;end if;
  if p_status not in ('active','frozen') or v_reason='' or length(v_reason)>500 then raise exception '顾客状态或变更原因无效';end if;
  select c.* into v_customer from public.salon_customers c join public.salon_customer_store_relations r on r.organization_id=c.organization_id and r.customer_id=c.id
    where c.organization_id=p_organization_id and c.id=p_customer_id and r.store_id=p_store_id for update of c;
  if not found then raise exception '顾客不存在或不属于当前门店';end if;
  if v_customer.status=p_status then raise exception '顾客已经是目标状态';end if;
  update public.salon_customers set status=p_status,updated_at=now() where organization_id=p_organization_id and id=p_customer_id;
  insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason)
    values(p_organization_id,p_store_id,p_actor_staff_id,'customer',p_customer_id::text,'status_change',jsonb_build_object('status',v_customer.status),jsonb_build_object('status',p_status),v_reason);
  v_response:=jsonb_build_object('customerId',p_customer_id,'status',p_status);
  update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_update_customer_relation(
  p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_customer_id bigint,
  p_request_key text,p_owner_staff_id bigint default null,p_source text default 'walkin',p_tags text[] default '{}'
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_before public.salon_customer_store_relations;v_source text:=btrim(coalesce(p_source,''));v_tags text[];v_response jsonb;
begin
  perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'customers','write');
  if v_source not in ('walkin','appointment','referral','online','import','other') then raise exception '顾客来源无效';end if;
  select coalesce(array_agg(distinct btrim(x) order by btrim(x)) filter(where btrim(x)<>''),'{}'::text[]) into v_tags from unnest(coalesce(p_tags,'{}')) x;
  if cardinality(v_tags)>20 or exists(select 1 from unnest(v_tags) x where length(x)>30) then raise exception '顾客标签最多20个且每个不超过30字';end if;
  v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'customer_relation','customer_relation_payload',hashtextextended(jsonb_build_object('customerId',p_customer_id,'owner',p_owner_staff_id,'source',v_source,'tags',v_tags)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_customer_id',p_customer_id,'p_owner_staff_id',p_owner_staff_id,'p_source',p_source,'p_tags',p_tags),'customers','write');
  if v_request.completed_at is not null then return v_request.response_json;end if;
  if p_owner_staff_id is not null and not exists(select 1 from public.salon_staff s where s.organization_id=p_organization_id and s.store_id=p_store_id and s.id=p_owner_staff_id and s.employment_status='active') then raise exception '负责人不是当前门店在职员工';end if;
  select * into v_before from public.salon_customer_store_relations r where r.organization_id=p_organization_id and r.store_id=p_store_id and r.customer_id=p_customer_id for update;
  if not found then raise exception '顾客不存在或不属于当前门店';end if;
  update public.salon_customer_store_relations set owner_staff_id=p_owner_staff_id,source=v_source,tags=v_tags where organization_id=p_organization_id and store_id=p_store_id and customer_id=p_customer_id;
  insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json)
    values(p_organization_id,p_store_id,p_actor_staff_id,'customer_relation',p_customer_id::text,'update',jsonb_build_object('ownerStaffId',v_before.owner_staff_id,'source',v_before.source,'tags',v_before.tags),jsonb_build_object('ownerStaffId',p_owner_staff_id,'source',v_source,'tags',v_tags));
  v_response:=jsonb_build_object('customerId',p_customer_id,'ownerStaffId',p_owner_staff_id,'source',v_source,'tags',v_tags);
  update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_create_catalog_item(
 p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,
 p_code text,p_item_type text,p_name text,p_category text default '',p_list_price numeric default 0,
 p_member_price numeric default 0,p_cost_price numeric default 0,p_unit text default '次',
 p_duration_minutes integer default null,p_stock_tracked boolean default false,p_safety_stock numeric default 0
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_id bigint;v_code text:=upper(btrim(coalesce(p_code,'')));v_name text:=btrim(coalesce(p_name,''));v_response jsonb;v_hash bigint;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'catalog','write');
 if v_code='' or length(v_code)>40 or v_name='' or length(v_name)>100 then raise exception '项目商品编号或名称无效';end if;
 if p_item_type not in ('service','product','package','year_card') then raise exception '项目商品类型无效';end if;
 if p_list_price<0 or p_member_price<0 or p_cost_price<0 or p_safety_stock<0 then raise exception '价格或安全库存不能为负数';end if;
 if p_duration_minutes is not null and p_duration_minutes not between 5 and 1440 then raise exception '服务时长无效';end if;
 if p_item_type<>'product' and (p_stock_tracked or p_safety_stock<>0) then raise exception '只有商品可以启用库存';end if;
 if nullif(btrim(coalesce(p_unit,'')),'') is null then raise exception '单位不能为空';end if;
 v_hash:=hashtextextended(jsonb_build_object('code',v_code,'type',p_item_type,'name',v_name,'category',btrim(coalesce(p_category,'')),'price',p_list_price,'memberPrice',p_member_price,'cost',p_cost_price,'unit',btrim(p_unit),'duration',p_duration_minutes,'tracked',p_stock_tracked,'safety',p_safety_stock)::text,0);
 v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'catalog_create','catalog_payload',v_hash,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_code',p_code,'p_item_type',p_item_type,'p_name',p_name,'p_category',p_category,'p_list_price',p_list_price,'p_member_price',p_member_price,'p_cost_price',p_cost_price,'p_unit',p_unit,'p_duration_minutes',p_duration_minutes,'p_stock_tracked',p_stock_tracked,'p_safety_stock',p_safety_stock),'catalog','write');
 if v_request.completed_at is not null then return v_request.response_json;end if;
 begin
  insert into public.salon_catalog_items(organization_id,item_type,code,name,category,list_price,member_price,cost_price,unit,duration_minutes)
   values(p_organization_id,p_item_type,v_code,v_name,btrim(coalesce(p_category,'')),round(p_list_price,2),round(p_member_price,2),round(p_cost_price,2),btrim(p_unit),p_duration_minutes) returning id into v_id;
 exception when unique_violation then raise exception '该项目商品编号已经存在';end;
 insert into public.salon_catalog_store_settings(organization_id,store_id,catalog_item_id,stock_tracked,safety_stock) values(p_organization_id,p_store_id,v_id,p_item_type='product' and p_stock_tracked,round(p_safety_stock,3));
 if p_item_type='product' and p_stock_tracked then insert into public.salon_inventory_balances(organization_id,store_id,catalog_item_id) values(p_organization_id,p_store_id,v_id);end if;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json)
  values(p_organization_id,p_store_id,p_actor_staff_id,'catalog_item',v_id::text,'create',jsonb_build_object('code',v_code,'type',p_item_type,'name',v_name,'stockTracked',p_stock_tracked,'safetyStock',p_safety_stock));
 v_response:=jsonb_build_object('catalogItemId',v_id,'code',v_code,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_enable_catalog_item(
 p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_catalog_item_id bigint,p_request_key text,p_stock_tracked boolean default false,p_safety_stock numeric default 0
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_type text;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'catalog','write');
 v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'catalog_enable','catalog_item',p_catalog_item_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_catalog_item_id',p_catalog_item_id,'p_stock_tracked',p_stock_tracked,'p_safety_stock',p_safety_stock),'catalog','write');if v_request.completed_at is not null then return v_request.response_json;end if;
 select item_type into v_type from public.salon_catalog_items where organization_id=p_organization_id and id=p_catalog_item_id and status='active';if not found then raise exception '项目商品不存在或已停用';end if;
 if p_safety_stock<0 or (v_type<>'product' and (p_stock_tracked or p_safety_stock<>0)) then raise exception '库存设置无效';end if;
 begin insert into public.salon_catalog_store_settings(organization_id,store_id,catalog_item_id,stock_tracked,safety_stock) values(p_organization_id,p_store_id,p_catalog_item_id,v_type='product' and p_stock_tracked,round(p_safety_stock,3));exception when unique_violation then raise exception '当前门店已经启用该项目商品';end;
 if v_type='product' and p_stock_tracked then insert into public.salon_inventory_balances(organization_id,store_id,catalog_item_id) values(p_organization_id,p_store_id,p_catalog_item_id);end if;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'catalog_store',p_catalog_item_id::text,'enable',jsonb_build_object('stockTracked',p_stock_tracked,'safetyStock',p_safety_stock));
 v_response:=jsonb_build_object('catalogItemId',p_catalog_item_id,'storeId',p_store_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_set_catalog_status(
 p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_catalog_item_id bigint,p_request_key text,p_status text,p_reason text
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_before text;v_reason text:=btrim(coalesce(p_reason,''));v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'catalog','write');
 v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'catalog_status','catalog_status_'||coalesce(p_status,''),p_catalog_item_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_catalog_item_id',p_catalog_item_id,'p_status',p_status,'p_reason',p_reason),'catalog','write');
 if v_request.completed_at is not null then return v_request.response_json;end if;
 if p_status not in ('active','disabled') or v_reason='' then raise exception '项目商品状态或原因无效';end if;
 select status into v_before from public.salon_catalog_store_settings where organization_id=p_organization_id and store_id=p_store_id and catalog_item_id=p_catalog_item_id for update;
 if not found then raise exception '项目商品不存在或不属于当前门店';end if;if v_before=p_status then raise exception '项目商品已经是目标状态';end if;
 update public.salon_catalog_store_settings set status=p_status,updated_at=now() where organization_id=p_organization_id and store_id=p_store_id and catalog_item_id=p_catalog_item_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'catalog_store',p_catalog_item_id::text,'status_change',jsonb_build_object('status',v_before),jsonb_build_object('status',p_status),v_reason);
 v_response:=jsonb_build_object('catalogItemId',p_catalog_item_id,'status',p_status);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_create_order(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,p_customer_id bigint default null,p_appointment_id bigint default null,p_notes text default '')
returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_request public.salon_operation_requests;v_id bigint;v_no text;v_hash bigint;v_response jsonb;begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'orders','write');
 if p_customer_id is not null and not exists(select 1 from public.salon_customers c join public.salon_customer_store_relations r on r.organization_id=c.organization_id and r.customer_id=c.id where c.organization_id=p_organization_id and c.id=p_customer_id and c.status='active' and r.store_id=p_store_id) then raise exception '顾客不存在、已冻结或不属于当前门店';end if;
 if p_appointment_id is not null and not exists(select 1 from public.salon_appointments a where a.organization_id=p_organization_id and a.store_id=p_store_id and a.id=p_appointment_id and (p_customer_id is null or a.customer_id=p_customer_id)) then raise exception '预约不存在、跨店或顾客不一致';end if;
 v_hash:=hashtextextended(jsonb_build_object('customer',p_customer_id,'appointment',p_appointment_id,'notes',btrim(coalesce(p_notes,'')))::text,0);v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'order_create','order_payload',v_hash,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_customer_id',p_customer_id,'p_appointment_id',p_appointment_id,'p_notes',p_notes),'orders','write');if v_request.completed_at is not null then return v_request.response_json;end if;
 v_no:='S'||p_store_id::text||'-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('public.salon_order_number_seq')::text,8,'0');insert into public.salon_orders(organization_id,store_id,order_no,customer_id,appointment_id,status,created_by_staff_id,notes) values(p_organization_id,p_store_id,v_no,p_customer_id,p_appointment_id,'draft',p_actor_staff_id,btrim(coalesce(p_notes,''))) returning id into v_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'order',v_id::text,'create',jsonb_build_object('orderNo',v_no,'customerId',p_customer_id,'appointmentId',p_appointment_id));v_response:=jsonb_build_object('orderId',v_id,'orderNo',v_no,'status','draft');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_replace_order_lines(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_order_id bigint,p_request_key text,p_lines jsonb,p_discount_reason text default '')
returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_request public.salon_operation_requests;v_order public.salon_orders;v_line jsonb;v_item public.salon_catalog_items;v_qty numeric;v_price numeric;v_discount numeric;v_staff bigint;v_subtotal numeric:=0;v_discount_total numeric:=0;v_payable numeric:=0;v_response jsonb;begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'orders','write');v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'order_lines','order_lines_payload',hashtextextended(jsonb_build_object('order',p_order_id,'lines',p_lines,'reason',btrim(coalesce(p_discount_reason,'')))::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_order_id',p_order_id,'p_lines',p_lines,'p_discount_reason',p_discount_reason),'orders','write');if v_request.completed_at is not null then return v_request.response_json;end if;
 select * into v_order from public.salon_orders where organization_id=p_organization_id and store_id=p_store_id and id=p_order_id for update;if not found then raise exception '订单不存在或不属于当前门店';end if;if v_order.status<>'draft' then raise exception '只有草稿订单可以修改明细';end if;if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 or jsonb_array_length(p_lines)>100 then raise exception '订单明细必须为1至100项';end if;
 delete from public.salon_order_lines where organization_id=p_organization_id and order_id=p_order_id;
 for v_line in select value from jsonb_array_elements(p_lines) loop
  select i.* into v_item from public.salon_catalog_items i join public.salon_catalog_store_settings s on s.organization_id=i.organization_id and s.catalog_item_id=i.id where i.organization_id=p_organization_id and i.id=nullif(v_line->>'catalogItemId','')::bigint and i.status='active' and s.store_id=p_store_id and s.status='active';if not found then raise exception '订单项目商品不存在或当前门店未启用';end if;
  v_qty:=round(coalesce(nullif(v_line->>'quantity','')::numeric,0),3);v_price:=round(coalesce(nullif(v_line->>'unitPrice','')::numeric,v_item.list_price),2);v_discount:=round(coalesce(nullif(v_line->>'discountAmount','')::numeric,0),2);v_staff:=nullif(v_line->>'staffId','')::bigint;
  if v_qty<=0 or v_price<0 or v_discount<0 or v_discount>v_qty*v_price then raise exception '订单明细数量、单价或优惠无效';end if;if v_staff is not null and not exists(select 1 from public.salon_staff s where s.organization_id=p_organization_id and s.store_id=p_store_id and s.id=v_staff and s.employment_status='active') then raise exception '服务员工不是当前门店在职员工';end if;
  v_subtotal:=v_subtotal+v_qty*v_price;v_discount_total:=v_discount_total+v_discount;v_payable:=v_payable+v_qty*v_price-v_discount;
  insert into public.salon_order_lines(organization_id,order_id,catalog_item_id,staff_id,quantity,unit_price,line_total,item_code,item_name,item_type,discount_amount) values(p_organization_id,p_order_id,v_item.id,v_staff,v_qty,v_price,round(v_qty*v_price-v_discount,2),v_item.code,v_item.name,v_item.item_type,v_discount);
 end loop;
 if v_discount_total>0 then perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'orders','discount');if nullif(btrim(p_discount_reason),'') is null then raise exception '优惠订单必须填写原因';end if;end if;
 update public.salon_orders set subtotal=round(v_subtotal,2),discount_total=round(v_discount_total,2),payable_total=round(v_payable,2),discount_reason=btrim(coalesce(p_discount_reason,'')),updated_at=now() where organization_id=p_organization_id and id=p_order_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'order',p_order_id::text,'replace_lines',jsonb_build_object('lineCount',jsonb_array_length(p_lines),'subtotal',round(v_subtotal,2),'discount',round(v_discount_total,2),'payable',round(v_payable,2),'requestKey',p_request_key),btrim(coalesce(p_discount_reason,'')));
 v_response:=jsonb_build_object('orderId',p_order_id,'lineCount',jsonb_array_length(p_lines),'subtotal',round(v_subtotal,2),'discountTotal',round(v_discount_total,2),'payableTotal',round(v_payable,2));update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_set_order_status(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_order_id bigint,p_request_key text,p_status text,p_reason text default '')
returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_request public.salon_operation_requests;v_order public.salon_orders;v_response jsonb;begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'orders','write');v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'order_status','order_status_'||coalesce(p_status,''),p_order_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_order_id',p_order_id,'p_status',p_status,'p_reason',p_reason),'orders','write');if v_request.completed_at is not null then return v_request.response_json;end if;select * into v_order from public.salon_orders where organization_id=p_organization_id and store_id=p_store_id and id=p_order_id for update;if not found then raise exception '订单不存在或不属于当前门店';end if;
 if not ((v_order.status='draft' and p_status in ('opened','cancelled')) or (v_order.status='opened' and p_status in ('in_service','awaiting_payment','cancelled')) or (v_order.status='in_service' and p_status in ('awaiting_payment','cancelled'))) then raise exception '订单状态流转无效';end if;if p_status<>'cancelled' and not exists(select 1 from public.salon_order_lines where organization_id=p_organization_id and order_id=p_order_id) then raise exception '空订单不能进入业务流程';end if;if p_status='cancelled' and nullif(btrim(p_reason),'') is null then raise exception '取消订单必须填写原因';end if;
 update public.salon_orders set status=p_status,opened_at=case when p_status='opened' then now() else opened_at end,updated_at=now() where organization_id=p_organization_id and id=p_order_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'order',p_order_id::text,'status_change',jsonb_build_object('status',v_order.status),jsonb_build_object('status',p_status),btrim(coalesce(p_reason,'')));v_response:=jsonb_build_object('orderId',p_order_id,'status',p_status);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_create_staff(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,p_staff_no text,p_display_name text,p_role_id bigint,p_position text default '',p_level_name text default '',p_base_salary numeric default 0) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'staff','write');if nullif(btrim(coalesce(p_staff_no,'')),'') is null or nullif(btrim(coalesce(p_display_name,'')),'') is null or p_base_salary<0 or (p_role_id is not null and not exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_role_id and status='active')) then raise exception '员工资料参数无效';end if;if p_role_id is not null then perform salon_private.assert_role_scope_admin(p_actor_staff_id,p_organization_id,p_role_id,'assignment_write');end if;v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'staff_create','staff_payload',hashtextextended(jsonb_build_object('no',upper(btrim(p_staff_no)),'name',btrim(p_display_name),'role',p_role_id,'position',btrim(coalesce(p_position,'')),'level',btrim(coalesce(p_level_name,'')),'salary',round(p_base_salary,2))::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_staff_no',p_staff_no,'p_display_name',p_display_name,'p_role_id',p_role_id,'p_position',p_position,'p_level_name',p_level_name,'p_base_salary',p_base_salary),'staff','write');if v_op.completed_at is not null then return v_op.response_json;end if;begin insert into public.salon_staff(organization_id,store_id,role_id,staff_no,display_name,position,level_name,base_salary) values(p_organization_id,p_store_id,p_role_id,upper(btrim(p_staff_no)),btrim(p_display_name),btrim(coalesce(p_position,'')),btrim(coalesce(p_level_name,'')),round(p_base_salary,2)) returning id into v_id;exception when unique_violation then raise exception '员工编号已经存在';end;if p_role_id is not null then insert into public.salon_staff_store_roles(organization_id,staff_id,store_id,role_id,assigned_by_staff_id,reason) values(p_organization_id,v_id,p_store_id,p_role_id,p_actor_staff_id,'创建员工时设置初始角色');end if;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'staff',v_id::text,'create',jsonb_build_object('staffNo',upper(btrim(p_staff_no)),'displayName',btrim(p_display_name),'position',btrim(coalesce(p_position,''))));v_response:=jsonb_build_object('staffId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_set_staff_status(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_target_staff_id bigint,p_request_key text,p_status text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_staff public.salon_staff;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'staff','write');if p_status not in('active','leave','departed') or nullif(btrim(coalesce(p_reason,'')),'') is null or (p_target_staff_id=p_actor_staff_id and p_status='departed') then raise exception '员工状态或变更原因无效';end if;v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'staff_status','staff_status_'||p_status,p_target_staff_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_target_staff_id',p_target_staff_id,'p_status',p_status,'p_reason',p_reason),'staff','write');if v_op.completed_at is not null then return v_op.response_json;end if;select * into v_staff from public.salon_staff where organization_id=p_organization_id and store_id=p_store_id and id=p_target_staff_id for update;if not found or v_staff.employment_status=p_status then raise exception '员工不存在或已经是目标状态';end if;update public.salon_staff set employment_status=p_status,effective_to=case when p_status='departed' then current_date else null end where organization_id=p_organization_id and id=p_target_staff_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'staff',p_target_staff_id::text,'status_change',jsonb_build_object('status',v_staff.employment_status),jsonb_build_object('status',p_status),btrim(p_reason));v_response:=jsonb_build_object('staffId',p_target_staff_id,'status',p_status);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_create_commission_rule(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,p_category text,p_name text,p_rate numeric,p_valid_from date,p_valid_to date default null) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'commission','write');if p_category not in('service','product') or nullif(btrim(coalesce(p_name,'')),'') is null or p_rate not between 0 and 100 or p_valid_from is null or (p_valid_to is not null and p_valid_to<p_valid_from) then raise exception '提成规则参数无效';end if;v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'commission_rule','commission_payload',hashtextextended(jsonb_build_object('category',p_category,'name',btrim(p_name),'rate',round(p_rate,3),'from',p_valid_from,'to',p_valid_to)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_category',p_category,'p_name',p_name,'p_rate',p_rate,'p_valid_from',p_valid_from,'p_valid_to',p_valid_to),'commission','write');if v_op.completed_at is not null then return v_op.response_json;end if;perform 1 from public.salon_stores where organization_id=p_organization_id and id=p_store_id for no key update;if exists(select 1 from public.salon_commission_rules where organization_id=p_organization_id and store_id=p_store_id and category=p_category and status='active' and daterange(valid_from,coalesce(valid_to,'infinity'::date),'[]') && daterange(p_valid_from,coalesce(p_valid_to,'infinity'::date),'[]')) then raise exception '该类别有效期内已有提成规则';end if;insert into public.salon_commission_rules(organization_id,store_id,category,name,rate,valid_from,valid_to,created_by_staff_id) values(p_organization_id,p_store_id,p_category,btrim(p_name),round(p_rate,3),p_valid_from,p_valid_to,p_actor_staff_id) returning id into v_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'commission_rule',v_id::text,'create',jsonb_build_object('category',p_category,'rate',round(p_rate,3),'validFrom',p_valid_from,'validTo',p_valid_to));v_response:=jsonb_build_object('commissionRuleId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_create_role(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,p_name text,p_data_scope text,p_permissions jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'settings','role_write');if nullif(btrim(coalesce(p_name,'')),'') is null or p_data_scope not in('self','store','organization') or jsonb_typeof(p_permissions)<>'array' or jsonb_array_length(p_permissions) not between 1 and 100 or (p_data_scope='self' and exists(select 1 from jsonb_array_elements_text(p_permissions) x where x<>'payroll/read')) or exists(select 1 from jsonb_array_elements_text(p_permissions) x where split_part(x,'/',1)='' or split_part(x,'/',2)='' or split_part(x,'/',3)<>'' or not exists(select 1 from public.salon_permission_catalog c where c.resource=split_part(x,'/',1) and c.action=split_part(x,'/',2))) then raise exception '角色名称、范围或权限无效';end if;if p_data_scope='organization' and not exists(select 1 from public.salon_staff_store_roles a join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.data_scope='organization' and r.status='active' join public.salon_role_permissions rp on rp.role_id=r.id and rp.resource='settings' and rp.action='role_write' where a.organization_id=p_organization_id and a.staff_id=p_actor_staff_id and a.status='active' and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date)) then raise exception '只有组织级管理员可以创建组织级角色';end if;v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'role_create','role_payload',hashtextextended(jsonb_build_object('name',btrim(p_name),'scope',p_data_scope,'permissions',p_permissions)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_name',p_name,'p_data_scope',p_data_scope,'p_permissions',p_permissions),'settings','role_write');if v_op.completed_at is not null then return v_op.response_json;end if;begin insert into public.salon_roles(organization_id,name,data_scope) values(p_organization_id,btrim(p_name),p_data_scope) returning id into v_id;exception when unique_violation then raise exception '角色名称已经存在';end;insert into public.salon_role_permissions(role_id,resource,action) select v_id,split_part(x,'/',1),split_part(x,'/',2) from(select distinct value x from jsonb_array_elements_text(p_permissions))q;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'role',v_id::text,'create',jsonb_build_object('name',btrim(p_name),'dataScope',p_data_scope,'permissions',p_permissions));v_response:=jsonb_build_object('roleId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_set_role_status(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_role_id bigint,p_request_key text,p_status text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_op public.salon_operation_requests;v_before text;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'settings','role_write');
 perform salon_private.assert_role_scope_admin(p_actor_staff_id,p_organization_id,p_role_id,'role_write');
 if p_status not in('active','disabled') or nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception '角色状态或原因无效';end if;
 v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'role_status','role_status_'||p_status,p_role_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_role_id',p_role_id,'p_status',p_status,'p_reason',p_reason),'settings','role_write');if v_op.completed_at is not null then return v_op.response_json;end if;
 select status into v_before from public.salon_roles where organization_id=p_organization_id and id=p_role_id for update;if not found or v_before=p_status then raise exception '角色不存在或已经是目标状态';end if;
 if p_status='disabled' and exists(select 1 from public.salon_staff_store_roles where organization_id=p_organization_id and role_id=p_role_id and status='active') then raise exception '角色仍有在用员工，不能停用';end if;
 update public.salon_roles set status=p_status where organization_id=p_organization_id and id=p_role_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'role',p_role_id::text,'status_change',jsonb_build_object('status',v_before),jsonb_build_object('status',p_status),btrim(p_reason));
 v_response:=jsonb_build_object('roleId',p_role_id,'status',p_status);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;
end$$;

create or replace function public.salon_assign_staff_store_role(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_target_staff_id bigint,p_role_id bigint,p_request_key text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'settings','assignment_write');
 perform salon_private.assert_role_scope_admin(p_actor_staff_id,p_organization_id,p_role_id,'assignment_write');
 if nullif(btrim(coalesce(p_reason,'')),'') is null or not exists(select 1 from public.salon_staff where organization_id=p_organization_id and id=p_target_staff_id and employment_status<>'departed') or not exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_role_id and status='active') then raise exception '员工、角色或分配原因无效';end if;
 v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'staff_assign','staff_role',hashtextextended(jsonb_build_object('staff',p_target_staff_id,'store',p_store_id,'role',p_role_id)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_target_staff_id',p_target_staff_id,'p_role_id',p_role_id,'p_reason',p_reason),'settings','assignment_write');if v_op.completed_at is not null then return v_op.response_json;end if;
 begin insert into public.salon_staff_store_roles(organization_id,staff_id,store_id,role_id,assigned_by_staff_id,reason) values(p_organization_id,p_target_staff_id,p_store_id,p_role_id,p_actor_staff_id,btrim(p_reason)) returning id into v_id;exception when unique_violation then raise exception '员工在该门店已有有效角色';end;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'staff_store_role',v_id::text,'assign',jsonb_build_object('staffId',p_target_staff_id,'roleId',p_role_id),btrim(p_reason));
 v_response:=jsonb_build_object('assignmentId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;
end$$;

create or replace function public.salon_transfer_staff(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_target_staff_id bigint,p_target_store_id bigint,p_target_role_id bigint,p_request_key text,p_effective_date date,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_op public.salon_operation_requests;v_staff public.salon_staff;v_assignment_id bigint;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_target_store_id,'settings','assignment_write');
 perform salon_private.assert_role_scope_admin(p_actor_staff_id,p_organization_id,p_target_role_id,'assignment_write');
 if p_target_staff_id=p_actor_staff_id or p_effective_date is null or p_effective_date<>current_date or nullif(btrim(coalesce(p_reason,'')),'') is null or not exists(select 1 from public.salon_stores where organization_id=p_organization_id and id=p_target_store_id and status='active') or not exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_target_role_id and status='active') then raise exception '调店参数无效';end if;
 v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'staff_transfer','staff_transfer',hashtextextended(jsonb_build_object('staff',p_target_staff_id,'from',p_store_id,'to',p_target_store_id,'role',p_target_role_id,'date',p_effective_date)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_target_staff_id',p_target_staff_id,'p_target_store_id',p_target_store_id,'p_target_role_id',p_target_role_id,'p_effective_date',p_effective_date,'p_reason',p_reason),'settings','assignment_write');if v_op.completed_at is not null then return v_op.response_json;end if;
 select * into v_staff from public.salon_staff where organization_id=p_organization_id and store_id=p_store_id and id=p_target_staff_id and employment_status<>'departed' for update;if not found or p_store_id=p_target_store_id then raise exception '员工不属于原门店或目标门店相同';end if;
 update public.salon_staff_store_roles set status='ended',effective_to=p_effective_date where organization_id=p_organization_id and staff_id=p_target_staff_id and store_id=p_store_id and status='active';
 insert into public.salon_staff_store_roles(organization_id,staff_id,store_id,role_id,effective_from,assigned_by_staff_id,reason) values(p_organization_id,p_target_staff_id,p_target_store_id,p_target_role_id,p_effective_date,p_actor_staff_id,btrim(p_reason)) returning id into v_assignment_id;
 update public.salon_staff set store_id=p_target_store_id,role_id=p_target_role_id,employment_status='active',effective_from=p_effective_date,effective_to=null where organization_id=p_organization_id and id=p_target_staff_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_target_store_id,p_actor_staff_id,'staff',p_target_staff_id::text,'transfer',jsonb_build_object('storeId',p_store_id,'roleId',v_staff.role_id),jsonb_build_object('storeId',p_target_store_id,'roleId',p_target_role_id,'effectiveDate',p_effective_date),btrim(p_reason));
 v_response:=jsonb_build_object('staffId',p_target_staff_id,'storeId',p_target_store_id,'assignmentId',v_assignment_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;
end$$;

create or replace function public.salon_list_payroll(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_month date default null) returns setof public.salon_payroll_runs language plpgsql security invoker set search_path='' as $$
declare v_non_self boolean;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'payroll','read');
 select exists(select 1 from public.salon_staff_store_roles a join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.status='active' and r.data_scope in('store','organization') join public.salon_role_permissions rp on rp.role_id=r.id and rp.resource='payroll' and rp.action='read' where a.organization_id=p_organization_id and a.staff_id=p_actor_staff_id and a.status='active' and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date) and (r.data_scope='organization' or a.store_id=p_store_id)) into v_non_self;
 return query select * from public.salon_payroll_runs p where p.organization_id=p_organization_id and p.store_id=p_store_id and (p_month is null or p.payroll_month=p_month) and (v_non_self or p.staff_id=p_actor_staff_id) order by p.payroll_month desc,p.id desc;
end$$;

create or replace function public.salon_list_staff_stores(p_actor_staff_id bigint,p_organization_id bigint) returns table(store_id bigint,code text,name text,data_scope text) language plpgsql security invoker set search_path='' as $$begin if not exists(select 1 from public.salon_organizations where id=p_organization_id and status='active') or not exists(select 1 from public.salon_staff where organization_id=p_organization_id and id=p_actor_staff_id and employment_status='active') then raise exception '员工不存在或已停用';end if;return query with access as(select st.id,st.code,st.name,r.data_scope from public.salon_staff_store_roles a join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.status='active' join public.salon_stores st on st.organization_id=a.organization_id and st.status='active' and (r.data_scope='organization' or st.id=a.store_id) where a.organization_id=p_organization_id and a.staff_id=p_actor_staff_id and a.status='active' and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date)) select a.id,a.code,a.name,case when bool_or(a.data_scope='organization') then 'organization' else 'store' end from access a group by a.id,a.code,a.name order by a.id;end$$;
